#!/usr/bin/env node
'use strict';

/**
 * Lari self-teaching coding loop.
 *
 * The thesis: Lari does not learn to code from reading code. It learns by
 * doing — generate a task, attempt it, run the code in a sandbox, verify the
 * output, retain what works, study what fails.
 *
 * Every retained solution is verified working, not pattern-matched. Slower
 * than an LLM at first. But the slowness disappears once the library exists:
 * then it is instant recall of proven code.
 *
 * Cycle:
 *   1. Task: from the seed library, or generated by composing mastered tasks.
 *   2. Attempt: known solutions first, then pattern composition, then mutation.
 *   3. Verify: run in a sandbox with a timeout, compare against the task's
 *      oracle (expected stdout or a test snippet).
 *   4. Learn: success -> solution retained permanently in
 *      model.lariCodeGeneration.solutions. Failure -> recorded with the error,
 *      becomes a learning goal for the research loop.
 */

const fs = require('fs');
const os = require('os');
const path = require('path');
const { spawnSync } = require('child_process');

// ---------------------------------------------------------------------------
// Sandbox execution
// ---------------------------------------------------------------------------

const LANGUAGE_RUNNERS = {
  python: { command: 'python3', args: [], ext: '.py' },
  javascript: { command: 'node', args: [], ext: '.js' },
  go: { command: 'go', args: ['run'], ext: '.go' }
};

/**
 * Run code in a sandbox: temp dir, hard timeout, stdout/stderr captured.
 * Returns { ok, stdout, stderr, exitCode, timedOut }.
 */
function runCodeSandbox(language, code, options = {}) {
  const runner = LANGUAGE_RUNNERS[language];
  if (!runner) return { ok: false, stdout: '', stderr: `unsupported language: ${language}`, exitCode: -1, timedOut: false };
  const timeoutMs = options.timeoutMs || 10000;
  let dir = null;
  try {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'lari-code-'));
    const file = path.join(dir, `task${runner.ext}`);
    fs.writeFileSync(file, String(code || ''));
    const run = spawnSync(runner.command, [...runner.args, file, ...(options.args || [])], {
      cwd: dir, encoding: 'utf8', timeout: timeoutMs, windowsHide: true,
      maxBuffer: 1024 * 1024
    });
    const timedOut = run.error && (run.error.code === 'ETIMEDOUT' || /timed out/i.test(run.error.message || ''));
    return {
      ok: !timedOut && run.status === 0,
      stdout: String(run.stdout || ''),
      stderr: String(run.stderr || ''),
      exitCode: run.status,
      timedOut: !!timedOut
    };
  } catch (error) {
    return { ok: false, stdout: '', stderr: String((error && error.message) || error), exitCode: -1, timedOut: false };
  } finally {
    if (dir) { try { fs.rmSync(dir, { recursive: true, force: true }); } catch (_) {} }
  }
}

