/**
 * Generate candidate code for a task. Returns array of { code, source }.
 * Order: retained solutions first, then pattern matches.
 */
function generateCandidates(model, task) {
  const candidates = [];
  const retained = findRetainedSolution(model, task);
  if (retained && retained.code) {
    candidates.push({ code: retained.code, source: `retained:${retained.taskId}` });
  }
  for (const pattern of CODE_PATTERNS) {
    if (pattern.language !== task.language) continue;
    if (!pattern.match.test(task.description || '')) continue;
    try {
      const code = pattern.build(task);
      if (code && !candidates.some(c => c.code === code)) {
        candidates.push({ code, source: `pattern:${pattern.id}` });
      }
    } catch (_) {}
  }
  // Learned patterns: derived from research, verified in the sandbox.
  for (const lp of getLearnedPatterns(model)) {
    if (lp.language !== task.language) continue;
    try {
      const re = new RegExp(lp.matchSource, 'i');
      if (!re.test(task.description || '')) continue;
      const code = instantiateLearnedPattern(lp, task);
      if (code && !candidates.some(c => c.code === code)) {
        candidates.push({ code, source: `learned:${lp.id}` });
      }
    } catch (_) {}
  }
  return candidates;
}

// ---------------------------------------------------------------------------
// Verification
// ---------------------------------------------------------------------------

function normalizeOutput(text) {
  return String(text || '').replace(/\r\n/g, '\n').trim().replace(/\n+$/, '');
}

function verifyAttempt(task, runResult) {
  if (!runResult) return { passed: false, reason: 'no_result' };
  if (runResult.timedOut) return { passed: false, reason: 'timeout', detail: runResult.stderr.slice(0, 200) };
  if (!runResult.ok) {
    return { passed: false, reason: 'runtime_error', detail: (runResult.stderr || '').slice(0, 300) };
  }
  const verify = task.verify || {};
  if (verify.type === 'stdout') {
    const actual = normalizeOutput(runResult.stdout);
    const expected = normalizeOutput(verify.expected);
    if (actual === expected) return { passed: true, reason: 'output_match' };
    return { passed: false, reason: 'output_mismatch', detail: `expected ${JSON.stringify(expected.slice(0, 100))}, got ${JSON.stringify(actual.slice(0, 100))}` };
  }
  if (verify.type === 'exit_code') {
    const expected = verify.expected == null ? 0 : verify.expected;
    if (runResult.exitCode === expected) return { passed: true, reason: 'exit_code_match' };
    return { passed: false, reason: 'exit_code_mismatch', detail: `exit ${runResult.exitCode}, stderr: ${(runResult.stderr || '').slice(0, 200)}` };
  }
  return { passed: false, reason: 'unknown_verify_type' };
}

// ---------------------------------------------------------------------------
// The self-teaching loop
// ---------------------------------------------------------------------------

function ensureCodeGeneration(model) {
  model.lariCodeGeneration = model.lariCodeGeneration || {};
  model.lariCodeGeneration.solutions = model.lariCodeGeneration.solutions || [];
  model.lariCodeGeneration.practiceLog = model.lariCodeGeneration.practiceLog || [];
  model.lariCodeGeneration.learningGoals = model.lariCodeGeneration.learningGoals || [];
  return model.lariCodeGeneration;
}

function retainSolution(model, task, code, source) {
  const cg = ensureCodeGeneration(model);
  // Do not duplicate.
  if (cg.solutions.some(s => s.taskId === task.id)) return false;
  cg.solutions.push({
    taskId: task.id,
    language: task.language,
    description: task.description,
    tags: task.tags || [],
    code: code,
    source: source,
    verifiedAt: new Date().toISOString(),
    verifyType: (task.verify || {}).type || 'stdout'
  });
  return true;
}

function logPractice(model, task, attempt) {
  const cg = ensureCodeGeneration(model);
  cg.practiceLog.push({
    taskId: task.id,
    timestamp: new Date().toISOString(),
    passed: attempt.verification.passed,
    reason: attempt.verification.reason,
    source: attempt.source
  });
  // Keep the log bounded.
  if (cg.practiceLog.length > 200) cg.practiceLog = cg.practiceLog.slice(-200);
}

function recordLearningGoal(model, task, failure) {
  const cg = ensureCodeGeneration(model);
  cg.learningGoals.push({
    taskId: task.id,
    description: task.description,
    language: task.language,
    tags: task.tags || [],
    failureReason: failure.reason,
    failureDetail: (failure.detail || '').slice(0, 200),
    // Carry the oracle so the research loop can verify against it later.
    expectedOutput: task.verify && task.verify.type === 'stdout' ? task.verify.expected : null,
    createdAt: new Date().toISOString(),
    status: 'open'
  });
  if (cg.learningGoals.length > 50) cg.learningGoals = cg.learningGoals.slice(-50);
}

/**
 * Teach one task: generate candidates, run each in the sandbox, verify.
 * Returns { taskId, passed, code, source, verification, attempts }.
 */
function selfTeachCodingTask(model, task, options = {}) {
  const maxAttempts = options.maxAttempts || 3;
  const candidates = generateCandidates(model, task);
  const result = {
    taskId: task.id,
    passed: false,
    code: null,
    source: null,
    verification: null,
    attempts: []
  };
  const tried = candidates.slice(0, maxAttempts);
  if (!tried.length) {
    result.verification = { passed: false, reason: 'no_candidates' };
    recordLearningGoal(model, task, result.verification);
    logPractice(model, task, result);
    return result;
  }
  for (const candidate of tried) {
    const runResult = runCodeSandbox(task.language, candidate.code, options);
    const verification = verifyAttempt(task, runResult);
    const attemptRecord = {
      source: candidate.source,
      code: candidate.code,
      runOk: runResult.ok,
      verification
    };
    result.attempts.push(attemptRecord);
    if (verification.passed) {
      result.passed = true;
      result.code = candidate.code;
      result.source = candidate.source;
      result.verification = verification;
      retainSolution(model, task, candidate.code, candidate.source);
      break;
    }
    result.verification = verification;
  }
  if (!result.passed) {
    recordLearningGoal(model, task, result.verification || { reason: 'all_failed' });
  }
  logPractice(model, task, result);
  return result;
}

/**
 * Run a full self-teaching cycle over seed tasks (and optionally generated
 * variants). Returns a summary.
 */
function runCodingSelfTeachCycle(model, options = {}) {
  const cg = ensureCodeGeneration(model);
  const tasks = options.tasks || CODE_TASK_SEEDS;
  const maxTasks = options.maxTasks || tasks.length;
  const results = [];
  let passed = 0;
  for (const task of tasks.slice(0, maxTasks)) {
    // Skip tasks already mastered (have a retained solution).
    if (!options.retryMastered && cg.solutions.some(s => s.taskId === task.id)) {
      results.push({ taskId: task.id, passed: true, skipped: true });
      passed++;
      continue;
    }
    const r = selfTeachCodingTask(model, task, options);
    results.push({ taskId: task.id, passed: r.passed, source: r.source, reason: r.verification && r.verification.reason });
    if (r.passed) passed++;
  }
  return {
    total: results.length,
    passed,
    failed: results.length - passed,
    solutionsRetained: cg.solutions.length,
    openLearningGoals: cg.learningGoals.filter(g => g.status === 'open').length,
    results
  };
}

/**
 * Answer a user's coding request using the self-teaching machinery.
 * This is the chat bridge: try retained knowledge, then attempt + verify.
 * Returns { answer, code, verified } or null if it cannot do it.
 */
function answerCodingRequest(model, prompt, options = {}) {
  const lower = String(prompt || '').toLowerCase();
  const language = /\bjavascript\b|\bjs\b|\bnode\b/.test(lower) ? 'javascript'
    : /\bpython\b|\bpy\b/.test(lower) ? 'python'
    : 'python'; // default
  // Build an ad-hoc task from the prompt. We can only verify tasks whose
  // expected output we can derive — for now, match against seed tasks.
  // Distinctive keywords (fizzbuzz, fibonacci) count double: they identify
  // the task even when the phrasing differs.
  const taskWords = new Set(lower.split(/\W+/).filter(w => w.length > 3));
  let bestTask = null, bestScore = 0;
  for (const seed of CODE_TASK_SEEDS) {
    if (seed.language !== language) continue;
    const seedWords = new Set(String(seed.description || '').toLowerCase().split(/\W+/).filter(w => w.length > 3));
    let overlap = 0;
    for (const w of taskWords) {
      if (seedWords.has(w)) overlap += w.length >= 7 ? 2 : 1;
    }
    // Tag overlap also counts: it captures the task family.
    const promptTags = [];
    if (/fibonacci/.test(lower)) promptTags.push('sequence');
    if (/fizzbuzz/.test(lower)) promptTags.push('loop');
    if (/factorial/.test(lower)) promptTags.push('math');
    if (/palindrome|reverse/.test(lower)) promptTags.push('string');
    if (/prime/.test(lower)) promptTags.push('math');
    if (/vowel/.test(lower)) promptTags.push('string');
    if (/even|odd/.test(lower)) promptTags.push('condition');
    if (/largest|max|sum/.test(lower)) promptTags.push('math');
    const tagOverlap = (seed.tags || []).filter(t => promptTags.includes(t)).length;
    overlap += tagOverlap;
    if (overlap > bestScore) { bestTask = seed; bestScore = overlap; }
  }
  if (!bestTask || bestScore < 4) return null; // cannot verify: be honest, do not bluff
  const result = selfTeachCodingTask(model, bestTask, { ...options, maxAttempts: 2 });
  if (!result.passed || !result.code) return null;
  const fence = language === 'python' ? 'python' : 'javascript';
  return {
    answer: `Here is working code — I ran it and verified the output:\n\n\`\`\`${fence}\n${result.code}\n\`\`\``,
    code: result.code,
    verified: true,
    taskId: bestTask.id,
    source: result.source
  };
}

module.exports = {
  runCodeSandbox,
  CODE_TASK_SEEDS,
  CODE_PATTERNS,
  generateCandidates,
  verifyAttempt,
  selfTeachCodingTask,
  runCodingSelfTeachCycle,
  answerCodingRequest,
  getRetainedSolutions,
  ensureCodeGeneration,
  getLearnedPatterns,
  addLearnedPattern,
  generalizePattern,
  instantiateLearnedPattern
};
